[tool error]
{
  "ok": false,
  "name": "get_design_data",
  "error": {
    "type": "query_failed",
    "message": "no alignment named 'SR-100'",
    "hint": "this document owns no alignments, but its references carry ['DESIGN:SR-100'] -- name one of those to read its design"
  }
}

[tool error]
{
  "ok": false,
  "name": "place_curve_table",
  "error": {
    "type": "invalid_params",
    "message": "'C-2' is not of type 'integer' (at 'curves.1')",
    "hint": "params must match the schema; a valid example is included",
    "valid_params_schema": {
      "type": "object",
      "properties": {
        "space": {
          "type": "string",
          "minLength": 1,
          "description": "'model' (design space, US survey feet) or a sheet id/name (paper space, inches), e.g. 'SH-001' or 'C-101'"
        },
        "alignment": {
          "type": "string",
          "minLength": 1,
          "description": "this document's alignment, or a referenced one as 'BASE:ALIGN-1'"
        },
        "position": {
          "type": "array",
          "items": {
            "type": "number"
          },
          "minItems": 2,
          "maxItems": 2,
          "description": "top-left corner, paper inches"
        },
        "curves": {
          "type": "array",
          "items": {
            "type": "integer",
            "minimum": 1
          },
          "description": "the curves this sheet shows, by the alignment's own curve index (C-1, C-2 ...); default all"
        },
        "first_curve_number": {
          "type": "integer",
          "minimum": 1,
          "description": "the plan's number for the alignment's first curve (default 1): curve numbers run along the line and never restart on the next sheet, so a design holding a later part of the line numbers on from the sheet before"
        },
        "columns": {
          "type": "array",
          "items": {
            "type": "string",
            "minLength": 1
          },
          "minItems": 1,
          "description": "keys: curve, pi_sta, pc_sta, pt_sta, delta, direction, radius, tangent, length, external, mid_ordinate, chord, chord_bearing; default the Caltrans table: curve, radius, delta, tangent, length (No., R, Δ, T, L)"
        },
        "title": {
          "type": "string"
        },
        "text_height": {
          "type": "number",
          "exclusiveMinimum": 0
        },
        "layer": {
          "type": "string",
          "minLength": 1
        },
        "style": {
          "type": "string",
          "minLength": 1
        },
        "color": {
          "type": "string",
          "description": "named CAD color (black, red, yellow, green, cyan, blue, magenta, gray, white) or '#RRGGBB'"
        }
      },
      "required": [
        "space",
        "position"
      ],
      "additionalProperties": false
    },
    "example": {
      "space": "C-101",
      "alignment": "ALIGN-1",
      "position": [
        24.0,
        8.5
      ]
    }
  },
  "warnings": []
}

